WITH flattened_attrs AS (SELECT id, plan, effective_from, currency, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT CASE WHEN avg_tier_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, currency, ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS entry_price_per_usd, COUNT(DISTINCT plan) AS distinct_plans, SUM(avg_tier_price) FILTER (WHERE currency = 'THB') AS thb_total_avg_tier_price, PERCENT_RANK() OVER (PARTITION BY CASE WHEN avg_tier_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) DESC) AS entry_price_per_usd_percent_rank FROM flattened_attrs GROUP BY 1, 2 ORDER BY currency DESC;
